export const STRIDE=6;const g=0,x=1,N=2,S=3,I=540;let r=[],t=null,l=0,u=0,f=[];export function startRecording(o){return r=o.map(n=>n.settings.position),r.includes("ball")||r.push("ball"),t=new Float32Array(r.length*6*540),l=0,u=0,f=[],r.slice()}export function noteLeap(o,n){return!t||!o||!(n>0)?!1:(f.push({position:o,tick:l,step:n}),!0)}function R(o,n){let e=-1;for(const s of f)s.position===o&&s.tick<=n&&(e=(n-s.tick)*s.step);return e}function h(){if((l+1)*r.length*6<=t.length)return;const n=new Float32Array(t.length*2);n.set(t),t=n}export function record(o){if(!t)return;h();const n=l*r.length*6;t.fill(0,n,n+r.length*6);for(const e of o){const s=r.indexOf(e.settings.position);if(s===-1)continue;const i=n+s*6;t[i]=e.coords.x,t[i+1]=e.coords.y,t[i+2]=e.coords.z||0,t[i+3]=e.state&&e.state.xSpeed||0,t[i+4]=e.state&&e.state.ySpeed||0,t[i+5]=e.settings.benched?0:e.state&&e.state.hasBall?e.state.run?3:2:1}l+=1}export function frameCount(){return l}export function slotNames(){return r.slice()}export function frameAt(o,n){if(!t||l===0)return[];const e=Math.max(0,Math.min(l-1,Math.floor(o))),s=e*r.length*6,i=[];for(let c=0;c<r.length;c+=1){const a=s+c*6,d=r[c],p=f.length?R(d,e):-1;i.push({settings:{position:d,team:n?n(d):0,benched:t[a+5]===0},coords:{x:t[a],y:t[a+1],z:t[a+2]},state:{xSpeed:t[a+3],ySpeed:t[a+4],hasBall:t[a+5]===2||t[a+5]===3,run:t[a+5]===3,leaping:p>=0,leapFor:p}})}return i}export function focusAt(o){const n=frameAt(o),e=n.find(c=>c.state.hasBall&&!c.settings.benched);if(e)return{...e.coords,holder:e.settings.position};const s=n.find(c=>c.settings.position==="ball"&&!c.settings.benched);if(s&&(s.coords.x||s.coords.y))return{...s.coords,holder:""};const i=n.find(c=>c.settings.position==="qb");return i?{...i.coords,holder:""}:{x:0,y:0,z:0,holder:""}}export function rewind(){u=0}export function advance(o,n,e=1){return u+=o*n*e,u>=l}export function playheadFrame(){return u}export function isEmpty(){return l===0}export function discard(){t=null,r=[],l=0,u=0,f=[]}
